import json, hashlib, math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];SRC=ROOT/'analysis'/'original_front_sources'
FILES={'tips_shoulders':SRC/'C_tips_shoulders.json','outer_upper':SRC/'C_inlet_outer_upper_sides.json','lower_sides':SRC/'C_inlet_lower_sides.json','join_screen':SRC/'C_outer_side_join_screen.json','axis_gaps':SRC/'C_remaining_axis_gaps.json','axis_corners':SRC/'C_axis_corner_fragments.json','frame':SRC/'front_shared_frame_candidate.json'}
j={k:json.loads(p.read_text(encoding='utf-8')) for k,p in FILES.items()};scale=float(j['frame']['profiles'][2]['isotropic_mm_per_section_pixel']);th=128
case=lambda obj:next(c for c in obj['cases'] if c['threshold']==th)
tips=case(j['tips_shoulders'])['segments_pixel'];upper=case(j['outer_upper'])['segments_pixel'];lower=case(j['lower_sides'])['segments_pixel'];joins=[r for r in j['join_screen']['rows'] if r['threshold']==th];corners=case(j['axis_corners'])['segments_pixel'];coarse=next(r for r in j['axis_gaps']['rows'] if r['threshold']==th)['pairs']
classes=[('tip_left',tips[0],'lokales oberes/aesseres Fragment'),('tip_right',tips[1],'lokales oberes/aesseres Fragment'),('shoulder_left',tips[2],'lokales Schulterfragment'),('shoulder_right',tips[3],'lokales Schulterfragment'),('outer_inlet_upper_left',upper[0],'aeussere obere Einlaufseite'),('outer_inlet_upper_right',upper[1],'aeussere obere Einlaufseite'),('outer_inlet_lower_left',lower[0],'aeussere untere Einlaufseite'),('inner_inlet_lower_left',lower[1],'innere untere Einlaufseite'),('inner_inlet_lower_right',lower[2],'innere untere Einlaufseite'),('outer_inlet_lower_right',lower[3],'aeussere untere Einlaufseite')]
fragment_classes=[{'class':n,'points':len(s),'role':r,'station_skin_semantics_verified':False} for n,s,r in classes]
local=[{'side':r['side'],'gap_pixel':r['gap_pixel'],'gap_candidate_mm':r['gap_pixel']*scale,'meaning':'nur lokale Rasterkontinuitaet obere->untere aeussere Einlaufseite','skin_continuity_verified':False} for r in joins]
# Engste sichtbare Endpunkte direkt an der horizontalen Achsenueberdeckung.
outer_pairs=[('links',corners[0][-1],corners[2][0]),('rechts',corners[1][0],corners[3][0])]
refined_outer=[]
for side,a,b in outer_pairs:
 d=math.dist(a,b);refined_outer.append({'region':side+'_aeusserer_Achsenanschluss','a':a,'b':b,'visible_endpoint_gap_pixel':d,'visible_endpoint_gap_candidate_mm':d*scale,'axis_rows_occluding_source':[607,608,609,610,611,612],'measured_bridge':False})
central=[g for g in coarse if g['region'] in ('obere_vertikale_Achse','untere_vertikale_Achse')]
unmeasured=[{'region':g['region'],'a':g['a'],'b':g['b'],'visible_endpoint_gap_pixel':g['minimum_sample_gap_pixel'],'visible_endpoint_gap_candidate_mm':g['minimum_sample_gap_pixel']*scale,'measured_bridge':False} for g in central]+refined_outer
out={'status':'C_KONTUR_SEMANTIK_GETRENNT_ACHSSENOKKLUSION_VERFEINERT_KEINE_HAUTFREIGABE','threshold':th,'candidate_scale_mm_per_pixel':scale,'inputs':{k:{'path':str(p.relative_to(ROOT)).replace('\\','/'),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for k,p in FILES.items()},'fragment_classes':fragment_classes,'measured_local_continuities':local,'unmeasured_axis_occlusions':unmeasured,'coarse_outer_gap_screen_retained_for_traceability':[g for g in coarse if 'aeusserer_Achsenanschluss' in g['region']],'key_findings':['Obere und untere aeussere Einlaufseiten liegen bei Schwelle128 an Zeilen649/650 lokal nur 1Pixel auseinander.','Die spaeter erfassten Achseneckfragmente reichen bis y=606 und beginnen wieder ab y=613; die engste sichtbare aeussere Okklusion betraegt links7.071Pixel und rechts7.280Pixel.','Die fruehere15.264-Pixel-Angabe bleibt nur als konservativer grober Abstand weiter auseinanderliegender Referenzpunkte nachvollziehbar, nicht als engste Konturluecke.','Die Quellzeilen607..612 werden von der horizontalen Zeichnungsachse ueberlagert; der verdeckte Verlauf bleibt ungemessen.','Spitzen, Schultern, Einlaufseiten und Achsenfragmente duerfen nicht automatisch zu einer einzigen Stationshaut oder Seitenhuelle zusammengezogen werden.','Die interpolierte Seitenprojektion darf nicht ohne physische Zuordnung als obere/untere C-Stationskante verwendet werden.'],'loft_allowed':False,'master_change_allowed':False,'production_release':False,'next_step':'Vier offene C-Ketten gegen benachbarte B/C- und C/D-Seitenprojektionen und Einlauf-/Glove-Semantik pruefen; nur physisch gleichartige Kanten als Registrierungsanker zulassen.'}
OUT=SRC/'C_contour_semantics_screen.json';OUT.write_text(json.dumps(out,indent=2,ensure_ascii=False),encoding='utf-8');print(json.dumps(out,indent=2,ensure_ascii=False))
